CREATE TABLE IF NOT EXISTS `university` (
  `id` bigint(10) NOT NULL AUTO_INCREMENT,
  `name` varchar(200) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT NULL,
  `abbrevation` varchar(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT NULL,
  `description` text CHARACTER SET utf8 COLLATE utf8_unicode_ci,
  `accreditation` varchar(1) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT NULL,
  `types` varchar(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT NULL,
  `email` varchar(100) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT NULL,
  `website` varchar(100) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT NULL,
  `phone` varchar(100) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT NULL,
  `address` text CHARACTER SET utf8 COLLATE utf8_unicode_ci,
  `studentAmount` int(10) DEFAULT NULL,
  `map` text CHARACTER SET utf8 COLLATE utf8_unicode_ci,
  `cityId` bigint(10) DEFAULT NULL,
  `provinceId` bigint(10) DEFAULT NULL,
  `status` varchar(20) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT 'PUBLISHED',
  `partner` varchar(1) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT 'N',
  `featured` varchar(1) DEFAULT 'N',
  `popularity` double DEFAULT '0',
  `logo` text CHARACTER SET utf8 COLLATE utf8_unicode_ci,
  `banner` text,
  `admissionBanner` text CHARACTER SET utf8 COLLATE utf8_unicode_ci,
  `galleryBanner` text,
  `companyPartnerDescription` text CHARACTER SET utf8 COLLATE utf8_unicode_ci,
  `companyPartnerLogo` text CHARACTER SET utf8 COLLATE utf8_unicode_ci,
  `addressOthers` text,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `createdBy` varchar(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT '0',
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedBy` varchar(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT '0',
  `deletedAt` timestamp NULL DEFAULT NULL,
  `deletedBy` varchar(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1201 DEFAULT CHARSET=utf8mb4;

